const fileData = $input.first().json;
const webhookData = $('Webhook').first().json.body;
const task = webhookData.task;
const from = webhookData.from;
const to = webhookData.to;

if (!task || !from || !to) throw new Error('Missing params');

const sha = fileData.sha;
const rawContent = fileData.content.replace(/\n/g, '');
const content = Buffer.from(rawContent, 'base64').toString('utf8');

const sectionKeys = ['WAITING / BLOCKED', 'DONE THIS WEEK', 'IN PROGRESS', 'THIS WEEK', 'BACKLOG', 'DROPPED'];

function detectSection(line) {
  if (!line.startsWith('## ')) return undefined;
  const upper = line.toUpperCase();
  for (const key of sectionKeys) { if (upper.includes(key)) return key; }
  return null;
}

const lines = content.split('\n');
const result = [];
let currentSection = null;
let taskRemoved = false;
let taskLine = null;

for (const line of lines) {
  const sec = detectSection(line);
  if (sec !== undefined) currentSection = sec;
  if (line === '---') currentSection = null;
  if (!taskRemoved && currentSection === from && (line.startsWith('- [ ]') || line.startsWith('- [x]'))) {
    const lineText = line.replace(/^- \[.\]\s*/, '').trim();
    if (lineText === task) { taskLine = line; taskRemoved = true; continue; }
  }
  result.push(line);
}

if (!taskRemoved) throw new Error('Task not found in ' + from);

if (to === 'DONE THIS WEEK') taskLine = taskLine.replace('- [ ]', '- [x]');
else taskLine = taskLine.replace('- [x]', '- [ ]');

const finalLines = [];
currentSection = null;
let inserted = false;

for (const line of result) {
  const sec = detectSection(line);
  if (sec !== undefined) currentSection = sec;
  if (line === '---') currentSection = null;
  finalLines.push(line);
  if (!inserted && currentSection === to && line.startsWith('>')) {
    finalLines.push(taskLine);
    inserted = true;
  }
}

if (!inserted) throw new Error('Could not insert into ' + to);

const newContent = finalLines.join('\n');
const encoded = Buffer.from(newContent).toString('base64');
const message = 'kanban: move task to ' + to;

return [{ json: { sha: sha, encoded: encoded, message: message, task: task, from: from, to: to } }];

